'use client';

import { useState, useEffect } from 'react';
import Button from '../../Elements/Button';
import { useRouter } from 'next/navigation';
import EditModal from './EditModal';
import Modal from './Modal';

interface Admin {
  user_id: number;
  username: string;
  email: string | null;
  phone_number: string | null;
  role: 'owner' | 'manager' | 'prep';
  restaurant_id: number;
  status: 'active' | 'inactive';
  created_at: string;
  updated_at: string;
}

const API_URL = 'http://localhost:3000/managers';

export default function AdminManager() {
  const router = useRouter();
  const RESTAURANT_ID = 1;
  const [admins, setAdmins] = useState<Admin[]>([]);
  const [deleteModal, setDeleteModal] = useState(false);
  const [editModal, setEditModal] = useState(false);
  const [selectedAdmin, setSelectedAdmin] = useState<Admin | null>(null);
  const [successModal, setSuccessModal] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchManagers = async () => {
      setLoading(true);
      try {
        const response = await fetch(`${API_URL}/${RESTAURANT_ID}`);
        if (response.ok) {
          const data = await response.json();
          setAdmins(data);
        } else {
          console.error('Failed to fetch managers:', response.statusText);
        }
      } catch (error) {
        console.error('Failed to fetch managers:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchManagers();
  }, []);

  const handleEdit = async (updatedAdmin: Admin) => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/${updatedAdmin.user_id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(updatedAdmin),
      });

      if (response.ok) {
        setAdmins(admins.map(admin => 
          admin.user_id === updatedAdmin.user_id ? updatedAdmin : admin
        ));
        setEditModal(false);
        setSuccessModal(true);
      } else {
        console.error('Failed to update manager:', response.statusText);
      }
    } catch (error) {
      console.error('Failed to update manager:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (managerId: number) => {
    setLoading(true);
    try {
      const response = await fetch(`${API_URL}/${managerId}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        setAdmins(admins.filter(admin => admin.user_id !== managerId));
        setDeleteModal(false);
        setSuccessModal(true);
      } else {
        console.error('Failed to delete manager:', response.statusText);
      }
    } catch (error) {
      console.error('Failed to delete manager:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6 max-w-4xl mx-auto mt-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold underline">VIEW ADMIN</h1>
        <Button
          label="CREATE NEW ADMIN"
          onClick={() => router.push('/manager-dash/admin/add')}
          style={{
            backgroundColor: 'transparent',
            color: 'black',
            border: '1px solid black'
          }}
        />
      </div>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <div className="border rounded-lg overflow-hidden">
          <div className="bg-gray-100 p-4 border-b">
            <h2 className="text-xl font-semibold">Current Admins</h2>
          </div>
          <table className="w-full">
            <thead>
              <tr className="border-b">
                <th className="p-4 text-left w-16">ID</th>
                <th className="p-4 text-left">Username</th>
                <th className="p-4 text-left">Email</th>
                <th className="p-4 text-left">Phone</th>
                <th className="p-4 text-left">Role</th>
                <th className="p-4 text-left">Status</th>
                <th className="p-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {admins.map((admin) => (
                <tr key={admin.user_id} className="border-b">
                  <td className="p-4">{admin.user_id}</td>
                  <td className="p-4">{admin.username}</td>
                  <td className="p-4">{admin.email || '-'}</td>
                  <td className="p-4">{admin.phone_number || '-'}</td>
                  <td className="p-4">{admin.role}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded-full text-sm ${
                      admin.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                    }`}>
                      {admin.status}
                    </span>
                  </td>
                  <td className="p-4 text-right space-x-2">
                    <Button
                      label="EDIT"
                      onClick={() => {
                        setSelectedAdmin(admin);
                        setEditModal(true);
                      }}
                      style={{
                        backgroundColor: 'white',
                        color: 'black',
                        border: '1px solid black'
                      }}
                    />
                    <Button
                      label="DELETE"
                      onClick={() => {
                        setSelectedAdmin(admin);
                        setDeleteModal(true);
                      }}
                      style={{
                        backgroundColor: 'white',
                        color: 'black',
                        border: '1px solid black'
                      }}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <EditModal
        admin={selectedAdmin}
        isOpen={editModal}
        onClose={() => setEditModal(false)}
        onSave={handleEdit}
      />

      <Modal
        isOpen={deleteModal}
        onClose={() => setDeleteModal(false)}
        title="Delete Admin?"
      >
        <div className="flex justify-center gap-4">
          <Button
            label="DELETE"
            onClick={() => handleDelete(selectedAdmin?.user_id || 0)}
            style={{
              backgroundColor: 'white',
              color: 'black',
              border: '1px solid black'
            }}
          />
          <Button
            label="CANCEL"
            onClick={() => setDeleteModal(false)}
            style={{
              backgroundColor: 'white',
              color: 'black',
              border: '1px solid black'
            }}
          />
        </div>
      </Modal>

      <Modal
        isOpen={successModal}
        onClose={() => setSuccessModal(false)}
        title={selectedAdmin ? "Admin Updated" : "Update Success"}
      >
        <div className="flex justify-center">
          <Button
            label="CLOSE"
            onClick={() => setSuccessModal(false)}
            style={{
              backgroundColor: 'white',
              color: 'black',
              border: '1px solid black'
            }}
          />
        </div>
      </Modal>
    </div>
  );
} 